from pathlib import Path
import sys, html, shutil
ROOT=Path(__file__).parent
sys.path.insert(0,str(ROOT/'.build-deps'))
import markdown
H=ROOT/'history'; H.mkdir(exist_ok=True)
for name in ['index.html','demo.html','prd.html']:
    target=H/(name.replace('.html','-embedded-v3.10.html'))
    if (ROOT/name).exists() and not target.exists(): shutil.copy2(ROOT/name,target)
css='''*{box-sizing:border-box}body{margin:0;background:#f4f5f7;color:#20252d;font:16px/1.85 -apple-system,BlinkMacSystemFont,"Microsoft YaHei",sans-serif}header{background:#121417;padding:20px max(24px,calc((100vw - 1280px)/2));display:flex;gap:24px;flex-wrap:wrap}header a{color:#fff;text-decoration:none}header a:first-child{color:#ffce45;font-weight:700}main{max-width:1280px;margin:auto;padding:40px 32px 100px}h1{font-size:32px;line-height:1.4}h2{font-size:25px;border-bottom:1px solid #d9dde4;padding-bottom:12px;margin-top:48px}h3{font-size:20px;margin-top:36px}p{margin:16px 0}a{color:#166393}table{border-collapse:collapse;width:100%;font-size:14px;background:white;margin:20px 0}th,td{border:1px solid #dbe0e7;padding:13px 16px;text-align:left;vertical-align:top}th{background:#e9edf2}td:first-child{min-width:120px}img{max-width:100%;max-height:680px;object-fit:contain;object-position:left;border-radius:12px}p:has(>img){background:#e9edf2;padding:20px;border-radius:16px}p:has(>img)+p{font-size:13px;color:#68717e}code{background:#e5e9ef;padding:2px 5px;border-radius:4px}blockquote{border-left:4px solid #e5b329;padding:12px 24px;background:#fff9e7}.tag{color:#96700a;font-size:13px;letter-spacing:1px}.lead{font-size:21px;color:#627080;max-width:850px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:32px 0}.card{display:block;border:1px solid #dce0e7;border-radius:20px;background:#fff;padding:28px;text-decoration:none;color:inherit}.card h2{border:0;margin:0 0 10px}.card img{width:100%;height:280px;object-fit:contain;object-position:center;background:#111;border-radius:10px}.button{display:inline-flex;padding:12px 22px;background:#ffce45;color:#201b0a;border-radius:10px;text-decoration:none;font-weight:600}.note{font-size:14px;color:#68717e}.links{display:flex;gap:20px;align-items:center;flex-wrap:wrap}@media(max-width:760px){main{padding:24px 18px}.cards{grid-template-columns:1fr}table{display:block;overflow-x:auto}h1{font-size:27px}}'''
css+='td:first-child{width:144px}td img{max-height:440px;max-width:100%;vertical-align:top}td{overflow-wrap:anywhere}td p{margin:8px 0}'
nav='<header><a href="index.html">盖世远程 · 独立产品</a><a href="mobile.html">移动端 Demo</a><a href="mac.html">电脑端 Demo</a><a href="prd.html">PRD V4.11</a></header>'
def write(name,title,body):
    (ROOT/name).write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+css+'</style></head><body>'+nav+'<main>'+body+'</main></body></html>',encoding='utf-8')
text=(ROOT/'独立远程电脑PRD.md').read_text(encoding='utf-8-sig')
write('prd.html','盖世远程 · PRD V4.11 评审稿',markdown.markdown(text,extensions=['tables','fenced_code','sane_lists'])+'<p><a class="button" download href="独立远程电脑PRD.md">下载 Markdown PRD</a></p>')
body='''<p class="tag">独立产品 · V4.11 本地评审 · 2026.10.28</p><h1>打开盖世远程，连接自己的电脑。</h1><p class="lead">移动 App 与电脑客户端独立运行，共用盖世账号。登录后查看同账号电脑，主动发起连接，继续电脑上的游戏与工作。</p><div class="cards"><a class="card" href="mobile.html"><h2>移动 App</h2><p>我的设备 / 我的 · 按键与布局复用交互线框</p><img src="assets/standalone-mobile-login.png" alt="移动端独立登录页"><p><span class="button">打开移动端 Demo</span></p></a><a class="card" href="mac.html"><h2>电脑客户端</h2><p>默认扫码与验证码登录 · 登录后首次引导 · 更多与个人账户</p><img src="assets/standalone-desktop-login.png" alt="电脑端独立登录页"><p><span class="button">打开电脑端 Demo</span></p></a></div><div class="links"><a class="button" href="prd.html">阅读图文 PRD V4.11</a><a download href="独立远程电脑PRD.md">下载 Markdown</a><a href="mobile.html?state=list">直接查看设备页</a><a href="mobile.html?state=profile">查看我的</a><a href="mac.html?state=onboarding">电脑登录后引导</a><a href="mobile.html?state=login&amp;region=overseas">海外手机登录</a><a href="mac.html?state=login&amp;region=overseas">海外电脑登录</a><a href="mac.html?state=remote-settings">查看电脑设置</a></div><p class="note">演示登录：国内手机号13600008000，海外邮箱player@example.com；先获取验证码，填写123456，勾选协议后登录。符合格式的其他账号也可模拟登录，不是账号白名单，不发送真实短信或邮件。Demo顶部可用中文/English即时切换语言，地区及登录状态保持不变。</p><h2>从登录到完成远控</h2><img src="assets/standalone-flow.png" alt="独立远程产品完整流程"><p class="note">本地 Demo 仅模拟登录、二维码、设备、文件和远控，不发送真实账号或远程指令。按键与布局以交互线框演示盖世游戏既有流程，支持点击、编辑与分享码演示；真实云服务、首发系统、正式协议及授权接口尚待接入，详见 PRD 第五章。二维码可在本地识别，同源页面间仅模拟确认；真实跨设备授权仍需账号服务。</p><p class="note">本轮替代旧版游戏库和盖世 Mac 侧栏入口。V3.10 文档与嵌入式页面保留作历史基线；当前评审以本页链接的双端 Demo 和 V4.11 PRD 为准。</p>'''
write('index.html','盖世远程 · 独立产品评审',body)
write('demo.html','盖世远程 · 双端 Demo',body)
print('Built index.html, demo.html and prd.html')
